INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Peripheriegeräte > Scanner
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Scanner unabhängig von der verfügbaren Schnittstelle des Systems ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Müssen mit USB oder anderen Anschlüssen kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl von Scannern immer die Anforderungen an die Auflösung berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Auflösung entscheidet über Bildqualität"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Scangeschwindigkeit für alle Anwendungsfälle irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit wichtig bei hohem Volumen"}, {"text": "Ja", "correct": false, "because": "Geschwindigkeit beeinflusst Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Scanner ohne Rücksicht auf die Softwarekompatibilität ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Treiber und Software müssen kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Kompatibilität ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind teurere Scanner immer besser als günstigere Modelle?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität hängt von Anforderungen ab, nicht nur Preis"}, {"text": "Ja", "correct": false, "because": "Preis ≠ Qualität"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines Scanners am wichtigsten?', 3, '[{"text": "Nutzungsanforderungen", "correct": true, "because": "Bestimmen Auflösung und Typ"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird für moderne Scanner am häufigsten verwendet?', 2, '[{"text": "USB", "correct": true, "because": "Universeller Standard"}, {"text": "Parallelport", "correct": false, "because": "Veraltet"}, {"text": "SCSI", "correct": false, "because": "Historisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit wird zur Messung der Scanner-Auflösung verwendet?', 2, '[{"text": "DPI", "correct": true, "because": "Dots per Inch gibt Detailgenauigkeit an"}, {"text": "MHz", "correct": false, "because": "Geschwindigkeit, nicht Auflösung"}, {"text": "GB", "correct": false, "because": "Speichergröße"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Scannertyp eignet sich am besten für große Dokumentenmengen?', 3, '[{"text": "Dokumentenscanner mit ADF", "correct": true, "because": "Automatischer Einzug für Effizienz"}, {"text": "Flachbettscanner", "correct": false, "because": "Langsamer bei Volumen"}, {"text": "Handscanner", "correct": false, "because": "Für kleine Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Netzwerkscannern?', 2, '[{"text": "Gemeinsame Nutzung im Büro", "correct": true, "because": "Mehrere Nutzer können zugreifen"}, {"text": "Geringere Kosten", "correct": false, "because": "Oft teurer"}, {"text": "Höhere Auflösung", "correct": false, "because": "Nicht zwangsläufig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines Scanners?', 4, '[{"text": "Auflösung", "correct": true, "because": "Bestimmt Bildqualität"}, {"text": "Scangeschwindigkeit", "correct": true, "because": "Beeinflusst Effizienz"}, {"text": "Schnittstellenkompatibilität", "correct": true, "because": "Muss zum System passen"}, {"text": "Gewicht des Scanners", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Flachbettscanner?', 3, '[{"text": "Vielseitigkeit", "correct": true, "because": "Für Bücher und Fotos geeignet"}, {"text": "Hohe Bildqualität", "correct": true, "because": "Präzise Scans"}, {"text": "Einfache Bedienung", "correct": true, "because": "Intuitive Nutzung"}, {"text": "Hohe Scangeschwindigkeit", "correct": false, "because": "Langsamer als ADF"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl eines Scanners auftreten?', 3, '[{"text": "Inkompatibilität mit Software", "correct": true, "because": "Treiber fehlen"}, {"text": "Unzureichende Auflösung", "correct": true, "because": "Minderwertige Scans"}, {"text": "Langsame Scangeschwindigkeit", "correct": true, "because": "Ineffizient bei Volumen"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen können Scanner zusätzlich bieten?', 4, '[{"text": "Duplex-Scan", "correct": true, "because": "Beidseitiges Scannen"}, {"text": "ADF (Automatischer Dokumenteneinzug)", "correct": true, "because": "Für mehrere Seiten"}, {"text": "OCR (Text recognition)", "correct": true, "because": "Text digitalisieren"}, {"text": "Druckfunktion", "correct": false, "because": "Für Multifunktionsgeräte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen erfordern hohe Scanner-Auflösung?', 3, '[{"text": "Fotoscans", "correct": true, "because": "Detailgenauigkeit nötig"}, {"text": "Grafikdesign", "correct": true, "because": "Hohe Qualität erforderlich"}, {"text": "Archivierung", "correct": true, "because": "Klare Dokumente"}, {"text": "Einfache Texte", "correct": false, "because": "Geringere Auflösung ausreichend"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Scanner mit ADF sind für große Dokumentenmengen geeignet. b) Auflösung wird in GB gemessen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ADF ja, Auflösung in DPI"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) USB ist die gängigste Schnittstelle für Scanner. b) Flachbettscanner sind schneller als Dokumentenscanner.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "USB ja, Flachbett langsamer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) OCR ermöglicht Texterkennung bei Scannern. b) Alle Scanner sind netzwerkfähig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "OCR ja, Netzwerk optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Hohe DPI-Werte verbessern die Scanqualität. b) Scangeschwindigkeit ist für Fotoscans entscheidend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DPI ja, Geschwindigkeit weniger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Scanner benötigen kompatible Treiber. b) Auflösung ist bei Textdokumenten unerheblich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Treiber ja, Auflösung relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

